import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), '../../..')
const source = (relativePath) => readFileSync(resolve(projectRoot, relativePath), 'utf8')
let failures = 0

function check(name, callback) {
  try {
    callback()
    console.log(`PASS ${name}`)
  } catch (error) {
    failures += 1
    console.error(`FAIL ${name}: ${error.message}`)
  }
}

check('registration API exposes temporary-account creation and info routes', () => {
  const api = source('src/api/cyjg/info.js')
  assert.match(api, /export function createTempAccount\(/)
  assert.match(api, /\/company\/base\/createTempAccount/)
  assert.match(api, /export function getTempAccountInfo\(/)
  assert.match(api, /\/company\/base\/tempAccountInfo/)
})

check('user store keeps userType separate from formal roles and token', () => {
  const user = source('src/store/modules/user.js')
  const getters = source('src/store/getters.js')
  assert.match(user, /userType:\s*['"]{2}/)
  assert.match(user, /SET_USER_TYPE/)
  assert.match(user, /user\.userType/)
  assert.match(getters, /userType:\s*state\.user\.userType/)
})

check('temporary accounts bypass formal organization loading and dynamic routes', () => {
  const permission = source('src/permission/index.js')
  assert.match(permission, /userType\s*===?\s*['"]01['"]|['"]01['"]\s*===?\s*userType/)
  assert.match(permission, /ListInfo/)
  assert.match(permission, /GenerateRoutes/)
})

check('temporary-account login returns to the registration continuation', () => {
  const login = source('src/views/login.vue')
  assert.match(login, /userType/)
  assert.match(login, /\/register\/add/)
})

check('registration creates credentials once and reads the authenticated draft', () => {
  const register = source('src/views/register/index.vue')
  assert.match(register, /createTempAccount/)
  assert.match(register, /getTempAccountInfo/)
  assert.match(register, /expireTime/)
  assert.match(register, /password/)
})

if (failures > 0) {
  process.exitCode = 1
} else {
  console.log('All 5 registration contract checks passed.')
}
